qs_goal_teach() {
  case "$1" in
    'notice')
      q_say 'The notice says what happened and what to do. cat it.'
      ;;
    'search')
      q_say 'grep prints every line that contains a word. grep "map-room" logs/* searches all 31 logs at once and shows which file each line came from. Look for a visit in the middle of the night.'
      ;;
    'who')
      q_say 'The map room was opened at 02:51 on the 17th by badge 7714. grep 7714 staff.txt finds the one line with that badge. Then write the name into a new file with echo and >.'
      ;;
    'count')
      q_say 'A pipe, |, sends what one command prints into the next. grep -r 7714 logs finds every line in every log; | wc -l counts them; >> case-notes.txt adds the count to your notes. Three tools, one line.'
      ;;
    'locker')
      q_say 'find walks every folder under a starting point and prints the paths whose names match. find lockers -name "*otto*" finds Otto'\''s locker however deep it is. (Quote the pattern, so the shell doesn'\''t expand the * first.)'
      ;;
    'map')
      q_say 'A locker this ordinary is hiding something. Look closer: ls -a.'
      ;;
  esac
}

