qs_goal_solution() {
  case "$1" in
    'notice')
      printf '%s\n' 'cat notice.txt'
      ;;
    'search')
      printf '%s\n' 'grep "map-room" logs/*'
      ;;
    'who')
      printf '%s\n' 'grep 7714 staff.txt'
      printf '%s\n' 'echo "Otto Brandt" > case-notes.txt'
      ;;
    'count')
